// The headers every chunk of a chunked backup upload carries:
//   X-Upload-Id     UUID v4 generated by the client
//   X-Chunk-Index   0-based index of this chunk
//   X-Chunk-Total   total chunks in the upload
//   X-File-Size     total file size in bytes
// Zero imports, so the unit suite loads it as is.

export type UploadChunkHeaders = {
  uploadId: string;
  chunkIndex: number;
  chunkTotal: number;
  fileSize: number;
};

// A whole number of at least `min`, written in plain digits. An absent or
// empty header is missing — never 0, which `Number("")` made it, so a request
// without X-Chunk-Index read as chunk 0 and restarted the upload.
function wholeNumber(raw: string | null, min: number): number | null {
  if (raw === null || !/^\d{1,16}$/.test(raw)) return null;
  const n = Number(raw);
  return Number.isSafeInteger(n) && n >= min ? n : null;
}

/** The chunk's headers, or null when any is absent or malformed (a 400, before any upload work). */
export function parseUploadChunkHeaders(headers: Pick<Headers, "get">): UploadChunkHeaders | null {
  const uploadId = headers.get("x-upload-id") ?? "";
  const chunkIndex = wholeNumber(headers.get("x-chunk-index"), 0);
  const chunkTotal = wholeNumber(headers.get("x-chunk-total"), 1);
  const fileSize = wholeNumber(headers.get("x-file-size"), 1);
  if (!uploadId || chunkIndex === null || chunkTotal === null || fileSize === null) return null;
  // An index past the total is left to the session (out of order / no
  // upload): it names a chunk of SOME upload, just not a next one.
  return { uploadId, chunkIndex, chunkTotal, fileSize };
}
